import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

const VILLES = ['Tunis', 'Sfax', 'Sousse', 'Monastir', 'Nabeul', 'Bizerte', 'Kairouan', 'Ariana'];

export default function Profile() {
  const { user } = useAuth();
  const [form, setForm] = useState({
    user_prenom: '', user_nom: '', email: '', ville: '', bio: '', telephone: '',
    tarifs_matieres: [], photo_url: null
  });
  const [structure, setStructure] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    fetchProfile();
  }, []);

  const fetchProfile = async () => {
    try {
      const isProf = user?.role === 'professeur';
      const res = await api.get(isProf ? '/api/professeurs/me' : '/api/etudiants/me');
      setForm(res.data);

      if (isProf) {
        const resStruct = await api.get('/api/admin/referentiel/structure');
        setStructure(resStruct.data);
      }
      setLoading(false);
    } catch (e) {
      console.error("Erreur chargement", e);
      setLoading(false);
    }
  };

  // --- GESTION DES CHAMPS (Débloqués) ---
  const updateField = (key, val) => setForm({ ...form, [key]: val });

  // --- GESTION DES TARIFS ---
  const isSelected = (matId, nivId) => form.tarifs_matieres?.some(t => t.matiere_id === matId && t.niveau_id === nivId);

  const handleToggle = (matId, nivId) => {
    let updated = [...(form.tarifs_matieres || [])];
    if (isSelected(matId, nivId)) {
      updated = updated.filter(t => !(t.matiere_id === matId && t.niveau_id === nivId));
    } else {
      updated.push({ matiere_id: matId, niveau_id: nivId, tarif: 25 });
    }
    setForm({ ...form, tarifs_matieres: updated });
  };

  const handlePrice = (matId, nivId, price) => {
    const updated = form.tarifs_matieres.map(t => 
      (t.matiere_id === matId && t.niveau_id === nivId) ? { ...t, tarif: parseFloat(price) || 0 } : t
    );
    setForm({ ...form, tarifs_matieres: updated });
  };

  const handleSave = async () => {
    try {
      const isProf = user?.role === 'professeur';
      const payload = {
        nom: form.user_nom,
        prenom: form.user_prenom,
        ville: form.ville,
        telephone: form.telephone,
        bio: form.bio,
        ...(isProf ? { tarifs_complets: form.tarifs_matieres } : { niveau: form.niveau })
      };
      await api.put(isProf ? '/api/professeurs/me' : '/api/etudiants/me', payload);
      setSaved(true); setTimeout(() => setSaved(false), 3000);
      alert("✅ Profil et catégories enregistrés !");
    } catch (e) { alert("Erreur sauvegarde"); }
  };

  const inp = { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, color: 'var(--text)', padding: '12px', fontSize: '.9rem', width: '100%', outline: 'none', marginBottom: '15px' };

  if (loading) return <div style={{padding:50, textAlign:'center'}}>Chargement...</div>;

  return (
    <div style={{ padding: 32, maxWidth: 1200, margin: '0 auto' }}>

      {/* HEADER */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 20, marginBottom: 30, background: 'var(--card)', padding: 20, borderRadius: 20 }}>
        <div style={{ width: 80, height: 80, borderRadius: '50%', background: 'var(--accent)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '2rem' }}>
          {user?.role === 'professeur' ? '👨‍🏫' : '👨‍🎓'}
        </div>
        <div>
           <h2 style={{fontFamily:'Syne'}}>{form.user_prenom} {form.user_nom}</h2>
           <p style={{color:'var(--text2)'}}>{user?.role}</p>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: user?.role === 'professeur' ? '400px 1fr' : '1fr', gap: 30 }}>

        {/* IDENTITÉ */}
        <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
          <h3 style={{ marginBottom: 20 }}>👤 Mon Identité</h3>

          <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Prénom</label>
          <input style={inp} value={form.user_prenom || ''} onChange={e => updateField('user_prenom', e.target.value)} />

          <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Nom</label>
          <input style={inp} value={form.user_nom || ''} onChange={e => updateField('user_nom', e.target.value)} />

          <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Email (Identifiant)</label>
          <input style={{...inp, opacity: 0.6}} value={form.email || ''} readOnly />

          <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Téléphone</label>
          <input style={inp} placeholder="+216..." value={form.telephone || ''} onChange={e => updateField('telephone', e.target.value)} />

          <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Ville</label>
          <select style={inp} value={form.ville || ''} onChange={e => updateField('ville', e.target.value)}>
             {VILLES.map(v => <option key={v} value={v}>{v}</option>)}
          </select>

          <button onClick={handleSave} style={{ width:'100%', background:'var(--accent)', color:'#fff', border:'none', padding:14, borderRadius:12, fontWeight:600 }}>
             {saved ? '✅ Modifié !' : 'Enregistrer les modifications'}
          </button>
        </div>

        {/* CATALOGUE (Visible uniquement pour Prof) */}
        {user?.role === 'professeur' && (
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <h3 style={{ marginBottom: 20 }}>📚 Mes Enseignements & Tarifs</h3>
            {structure.map(dom => (
              <div key={dom.id} style={{ marginBottom: 30 }}>
                <div style={{ color: 'var(--accent)', fontWeight: 800, marginBottom: 15, borderBottom: '1px solid var(--border)' }}>📂 {dom.nom.toUpperCase()}</div>
                {dom.niveaux?.map(niv => (
                  <div key={niv.id} style={{ marginLeft: 15, marginBottom: 20 }}>
                    <div style={{ fontWeight: 700, fontSize: '.9rem', marginBottom: 10 }}>🎓 {niv.nom}</div>
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
                      {niv.matieres?.map(mat => {
                        const active = isSelected(mat.id, niv.id);
                        return (
                          <div key={mat.id} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: active ? 'rgba(108,99,255,0.08)' : 'var(--surface2)', padding: '10px 15px', borderRadius: 12, border: active ? '1px solid var(--accent)' : '1px solid transparent' }}>
                            <label style={{ fontSize: '.85rem', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 10 }}>
                              <input type="checkbox" checked={active} onChange={() => handleToggle(mat.id, niv.id)} />
                              {mat.nom}
                            </label>
                            {active && (
                              <div style={{display:'flex', alignItems:'center', gap:5}}>
                                <input type="number" value={form.tarifs_matieres.find(t=>t.matiere_id===mat.id && t.niveau_id===niv.id).tarif} onChange={e => handlePrice(mat.id, niv.id, e.target.value)} style={{ width: 55, background: 'var(--bg)', color: '#fff', border: 'none', textAlign: 'center', borderRadius: 5 }} />
                                <span style={{fontSize:'.7rem'}}>DT</span>
                              </div>
                            )}
                          </div>
                        );
                      })}
                    </div>
                  </div>
                ))}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
